command:
function child1 {
    echo "Child 1"
    sleep 3s
    echo "Child 1 end"
    exit 11
}

function parent {
    echo "Parent"
    sleep 1s
    echo "Parent end"
}

child1 &

parent
pkill -P ${$}

function pgrep() {
    ps aux | grep $1 | grep -v grep
}

do_stop() {
  kill $(</var/run/program.pid)
}

function kill_recurse() {
    cpids=`pgrep -P $1|xargs`
    for cpid in $cpids;
    do
        kill_recurse $cpid
    done
    echo "killing $1"
    kill -9 $1
}

#!/bin/sh
cat <<'END'
menuentry reboot {
  reboot
}
END

function needs_reboot {
  if [ -f /var/run/reboot-required ]; then
    read -p "Restart needed. Reboot? (y/N) " answer;
    if [ "$answer" = "y" -o "$answer" = "Y" ]; then
      reboot;
    fi
  else
    echo "No restart";
  fi
}

show_signals() {
  perl -e 'for(keys %SIG) {
      $SIG{$_} = eval "sub { print \"Got $_\\n\"; }";
    }
    while(1){sleep 1}'
}
export -f show_signals
echo | parallel --termseq TERM,200,TERM,100,TERM,50,KILL,25 \
  -u --timeout 1 show_signals

trap 'return; echo not reached' USR1
func() {
    kill -s USR1 $$
    echo reached
}
func

func()(
    trap "pkill -P $$; pkill -P $$; exit" TERM
    parallel --will-cite sleep ::: 60
)

kill_process() {
    pkill -SIGINT service_name
    sleep 1
    if [ -n "$(pgrep service_name)" ]; then
        pkill -SIGTERM service_name
        sleep 1
    fi 
    if [ -n "$(pgrep service_name)" ]; then
        pkill -SIGKILL service_name
        sleep 1
    fi 
    if [ -z "$(pgrep service_name)" ]; then
        rm -f /var/lock/subsys/service_name
    fi
}

start() {
    action $"Starting Service: " /sbin/service_name
}

stop() {
    action $"Stopping Service: " kill_process
}

restart() {
    stop
    start
}

stop_service() {
    local svc=$1
    systemctl --user stop "$svc" || (( $? == 5 ))
}

# make sure fg in a subshell doesn't try to start a parent's job
set -m
sleep 20 &
echo $(jobs)
echo $(fg %% ; jobs)
kill %1

# "return" in trap sets $? after trap...
# ...but not a nested one!
g() { echo Nested; return 22; }
trap "echo TERM;false;g" term
f() {
	(kill $$) &
	sleep 1
}
f
echo Zero:$?

function inner() {
  tail -f /dev/null
}

function outer() {
  inner
}

outer &
echo 'Before, $!: ' $!
echo 'Before, jobs -p: ' $(jobs -p)
echo 'Before, ps aux: ' $(ps aux | grep /dev/null | grep -v grep)

kill $!
echo 'After, $!: ' $!
echo 'After, jobs -p: ' $(jobs -p)
echo 'After, ps aux: ' $(ps aux | grep /dev/null | grep -v grep)

#!/bin/bash

# Set maximum amount of remaining firefox processes here
MAX_PROC=2

let COUNT=$(pgrep firefox | wc -l)
for (( i=1; i<=COUNT-MAX_PROC; i++ ))
do
  PID=$(pgrep -o firefox)
  kill $PID
# sleep 3
done

#!/bin/bash
function sleepH(){
    local sshd_pid=$(ps -p $$ -o ppid | tail -n 1)
    while true
    do
        if [[ `ps -p $$ -o ppid | tail -n 1` != $sshd_pid ]];then kill -HUP $$;fi;
        sleep 2
    done
}
sleepH &

tail -f /root/config.ini >/dev/null

function finish {
  # your cleanup here. e.g. kill any forked processes
  jobs -p | xargs kill
}
trap finish EXIT

print -u $ZTST_fd 'This test takes at least three seconds...'
fn1() {
  trap 'print TERM1' TERM
  fn2() { trap 'print TERM2; return 1' TERM; sleep 2; }
  fn2 &
  sleep 1
  kill -TERM $!
  sleep 2
}
fn1
